// O no 'influxdb out' espera:
//   msg.payload = [ {fields}, {tags} ]
// fields = valores medidos | tags = rotulos usados para filtrar/agrupar
msg.payload = [
    {
        temperatura: Number((20 + Math.random() * 10).toFixed(1)),
        umidade:     Number((40 + Math.random() * 20).toFixed(1))
    },
    { sensor: "sala-01", predio: "A" }
];
return msg;

// Uma mensagem por ponto, com horario proprio (msg.payload[0].time)
const agora = Date.now();
const msgs = [];
for (let i = 19; i >= 0; i--) {
    msgs.push({ payload: [
        {
            temperatura: Number((22 + Math.sin(i / 3) * 4 + Math.random()).toFixed(1)),
            umidade:     Number((50 + Math.cos(i / 4) * 8 + Math.random()).toFixed(1)),
            time:        new Date(agora - i * 60000)
        },
        { sensor: "sala-02", predio: "A" }
    ]});
}
return [msgs];

// payload que chega do MQTT:
//   { sensor, temperatura, umidade, horario }
const d = msg.payload;
msg.payload = [
    { temperatura: d.temperatura, umidade: d.umidade },
    { sensor: d.sensor, origem: "mqtt" }
];
return msg;
